    case INITIALIZE_PLATFORM_POSITION_PID_CONTROLLER: return isfinite(command->properties.initialize_platform_position_pid_controller.linear_kp) && isfinite(command->properties.initialize_platform_position_pid_controller.angular_kp) && isfinite(command->properties.initialize_platform_position_pid_controller.max_linear_speed) && isfinite(command->properties.initialize_platform_position_pid_controller.max_angular_speed) && isfinite(command->properties.initialize_platform_position_pid_controller.position_tolerance) && isfinite(command->properties.initialize_platform_position_pid_controller.heading_tolerance) && isfinite(command->properties.initialize_platform_position_pid_controller.linear_ki) && isfinite(command->properties.initialize_platform_position_pid_controller.linear_kd) && isfinite(command->properties.initialize_platform_position_pid_controller.linear_integral_limit) && isfinite(command->properties.initialize_platform_position_pid_controller.angular_ki) && isfinite(command->properties.initialize_platform_position_pid_controller.angular_kd) && isfinite(command->properties.initialize_platform_position_pid_controller.angular_integral_limit);
